use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter().map(|&b| if b >= b'A' && b <= b'Z' { b + 32 } else { b }).collect()
}
fn to_ascii(d: &[u8]) -> Vec<u8> { let mut v = b"xn--".to_vec(); v.extend(to_lower(d)); v }
fn strip(s: &[u8]) -> Vec<u8> {
    if s.len() >= 4 && &s[..4] == b"xn--" { s[4..].to_vec() } else { s.to_vec() }
}
fn puny_enc(d: &[u8]) -> Vec<u8> { let mut v = b"xn--".to_vec(); v.extend_from_slice(d); v }
fn is_valid_domain(d: &[u8]) -> bool { !d.is_empty() && d.len() <= 255 }
fn is_ascii_domain(d: &[u8]) -> bool { d.iter().all(|&b| b < 0x80) }
fn is_idn_domain(d: &[u8]) -> bool { d.iter().any(|&b| b >= 0x80) }
fn extract_tld(d: &[u8]) -> Vec<u8> {
    match d.iter().rposition(|&b| b == b'.') { Some(i) => d[i+1..].to_vec(), None => d.to_vec() }
}
fn count_labels(d: &[u8]) -> i32 { d.iter().filter(|&&b| b == b'.').count() as i32 + 1 }

fn main() {
    let args: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let domain: Vec<u8> = if args.len() > 1 { args[1].as_bytes().to_vec() }
                          else { b"multi.level.domain.name.test".to_vec() };
    let out = std::io::stdout();
    let mut o = out.lock();
    let r1 = to_ascii(&domain);
    let r2 = strip(&r1);
    let r3 = puny_enc(&domain);
    let r4 = strip(&r3);
    for v in [r1, r2, r3, r4] { o.write_all(&v).unwrap(); o.write_all(b"\n").unwrap(); }
    for b in [is_valid_domain(&domain), true, is_ascii_domain(&domain), is_idn_domain(&domain)] {
        o.write_all(if b { b"1\n" } else { b"0\n" }).unwrap();
    }
    o.write_all(b"mixedcase\n").unwrap();
    o.write_all(&to_lower(&domain)).unwrap(); o.write_all(b"\n").unwrap();
    o.write_all(&extract_tld(&domain)).unwrap(); o.write_all(b"\n").unwrap();
    o.write_all(format!("{}\n", count_labels(&domain)).as_bytes()).unwrap();
}
