use std::io::{BufRead, Write};
use std::os::unix::ffi::OsStrExt;
use std::process::Command;

fn unhex(s: &str) -> Vec<u8> {
    let s: String = s.chars().filter(|c| !c.is_whitespace()).collect();
    (0..s.len()/2).map(|i| u8::from_str_radix(&s[2*i..2*i+2], 16).unwrap()).collect()
}
fn hex(b: &[u8]) -> String { b.iter().map(|x| format!("{:02x}", x)).collect() }

fn run(bin: &str, arg: Option<&[u8]>) -> (Vec<u8>, Vec<u8>, i32) {
    let mut c = Command::new(bin);
    if let Some(a) = arg {
        c.arg(std::ffi::OsStr::from_bytes(a));
    }
    let o = c.output().expect("spawn");
    (o.stdout, o.stderr, o.status.code().unwrap_or(-1))
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let f = std::fs::File::open(&path).unwrap();
    let mut n = 0usize; let mut bad = 0usize;
    let so = std::io::stdout(); let mut o = so.lock();
    for line in std::io::BufReader::new(f).lines() {
        let line = line.unwrap();
        let line = line.trim_end();
        if line.is_empty() || line.starts_with('#') { continue; }
        // format: LABEL<TAB>HEXBYTES   (HEXBYTES may be "NOARG")
        let mut it = line.splitn(2, '\t');
        let label = it.next().unwrap();
        let hx = it.next().unwrap_or("");
        let argv: Option<Vec<u8>> = if hx == "NOARG" { None } else { Some(unhex(hx)) };
        n += 1;
        let (a_out, _a_err, a_code) = run("/workspace/dataset/test12_executable", argv.as_deref());
        let (b_out, _b_err, b_code) = run("/tmp/probe/model", argv.as_deref());
        if a_out != b_out || a_code != b_code {
            bad += 1;
            writeln!(o, "### DIVERGE [{}] arg_hex={} codes={}/{}", label, hx, a_code, b_code).unwrap();
            let al: Vec<&[u8]> = a_out.split(|&c| c==b'\n').collect();
            let bl: Vec<&[u8]> = b_out.split(|&c| c==b'\n').collect();
            writeln!(o, "  nlines bin={} model={}", al.len(), bl.len()).unwrap();
            for i in 0..al.len().max(bl.len()) {
                let x = al.get(i).copied().unwrap_or(b"<MISSING>");
                let y = bl.get(i).copied().unwrap_or(b"<MISSING>");
                if x != y {
                    writeln!(o, "  line{}: bin={} model={}", i+1, hex(x), hex(y)).unwrap();
                    writeln!(o, "          bin_s={:?} model_s={:?}",
                        String::from_utf8_lossy(x), String::from_utf8_lossy(y)).unwrap();
                }
            }
        }
    }
    writeln!(o, "TOTAL={} DIVERGENT={}", n, bad).unwrap();
}
